INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Project X Classification', N'Detects references to confidential Project X information', N'DataClassification', N'Regular', N'DataSensitivity', N'(?i)\bproject\s*x\b', N'High', 1, 1);
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Taiwan National ID', N'Detects Taiwan national identification card numbers by their official one-letter and nine-digit format.', N'DataClassification', N'Regular', N'DataSensitivity', N'(?i)(?<![A-Z0-9])[A-Z][12]\d{8}(?![A-Z0-9])', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Taiwan Business Administration Number (Tax ID)', N'Detects standalone eight-digit Taiwan Business Administration Numbers used as tax identifiers.', N'DataClassification', N'Regular', N'DataSensitivity', N'(?i)(?<![A-Z0-9])\d{8}(?![A-Z0-9])', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Taiwan NHI Card Number', N'Detects standalone twelve-digit Taiwan National Health Insurance card numbers.', N'DataClassification', N'Regular', N'DataSensitivity', N'(?i)(?<![A-Z0-9])\d{12}(?![A-Z0-9])', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Compliance - Personal Identifiers and Contact Data', N'Detects personal identifiers and contact details protected by privacy regulations.', N'DataClassification', N'AI', N'DataSensitivity', N'Content that contains or requests information identifying or contacting a natural person, including names tied to other personal details, home or work addresses, telephone numbers, email addresses, national identification numbers, passport numbers, tax identifiers, online identifiers, device or IP identifiers, or precise location data. Classify only when information relates to an identifiable person; do not classify fictional examples, blank templates, or general discussion of identity and privacy without personal data.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Compliance - Financial Account and Transaction Data', N'Detects personal financial account, payment, credit, and transaction records.', N'DataClassification', N'AI', N'DataSensitivity', N'Content that contains or requests financial data connected to a person or customer, including bank or payment-account identifiers, card details, account balances, transaction histories, loan or credit records, income, assets, insurance financial records, invoices, payment instructions, or know-your-customer and anti-money-laundering records. Classify only when concrete records, identifiers, amounts, or customer financial facts are present; do not classify general finance, budgeting, accounting, pricing, or regulatory discussion without personal or customer financial data.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Compliance - Health Genetic and Biometric Data', N'Detects health, medical, genetic, biometric, and disability information about a person.', N'DataClassification', N'AI', N'DataSensitivity', N'Content that contains or requests information about an identifiable person''s physical or mental health, medical history, diagnoses, treatment, prescriptions, disability, genetic characteristics, biological samples, biometric templates, fingerprints, facial recognition data, voiceprints, or health-insurance records. Classify only when the data concerns a real or identifiable person; do not classify general medical education, public-health guidance, or hypothetical examples without personal health, genetic, or biometric data.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Compliance - Protected Demographic Belief and Sexual Data', N'Detects protected demographic, belief, political, union, and sexual information about a person.', N'DataClassification', N'AI', N'DataSensitivity', N'Content that contains or requests information about an identifiable person''s racial or ethnic origin, nationality, religion or philosophical beliefs, political opinions, trade-union membership, sex life, sexual orientation, gender identity, marital or family status, or similar protected demographic characteristics. Classify only when the information is tied to a real or identifiable person; do not classify general demographic statistics, public policy, history, or fictional scenarios without personal data.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'Compliance - Employment Education Criminal and Social Data', N'Detects personal employment, education, criminal, family, and social-activity records.', N'DataClassification', N'AI', N'DataSensitivity', N'Content that contains or requests records about an identifiable person''s employment, occupation, performance, compensation, education, qualifications, criminal convictions or alleged offences, court or disciplinary history, family relationships, social activities, memberships, or personal life. Classify only when concrete records or facts concern a real or identifiable person; do not classify generic recruiting, education, legal, or social-policy discussion without personal records.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
/****** AI Data Classification Rules ******/
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [RuleScope], [SensitivityLevel], [Enabled], [DefaultRule], [CreatedBy], [IsLiveProject]) VALUES (1, N'API Keys and Secrets in Source Code', N'Detects embedded authentication credentials in source code and technical configuration.', N'DataClassification', N'AI', N'DataSensitivity', N'Classify source or configuration that exposes a concrete, unredacted authentication credential value. Match API keys, access tokens, bearer tokens, client secrets, private authentication tokens, and equivalent credentials when the value has a provider-specific format or a long random-looking string and appears in an authentication context. A single bare environment assignment such as OPENAI_API_KEY=sk-proj-<long random value> or SERVICE_API_KEY=sk_live_<long random value> counts as exposed code/configuration; no surrounding program or API call is required. Also match quoted code, scripts, command lines, HTTP Authorization headers, SDK initialization, JSON, and YAML. Do not match variable names alone, empty assignments, prose about keys, masked or redacted strings, or placeholder/example/test/dummy/fake credential values. In particular, YOUR_API_KEY, <api-key>, sequences of asterisks or x characters, and sk_test values are not exposed usable credentials. If there is no concrete non-placeholder value, return no match.', N'Data,Prompt,Response', N'High', 1, 1, 0, 0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Personal Information', N'', N'DataClassification', N'AI','Data Sensitivity', N'This refers to content that contains or requests Sensitive Personal Information, including full, first, middle, or last names, account names, and contact details such as addresses, phone numbers, or email addresses; financial data including account numbers, IBANs, credit card numbers, CVV codes, and issuers; government or demographic identifiers such as SSN, gender, sex, or sex type; technical identifiers like passwords, IP addresses (IPv4/IPv6); and vehicle information such as VIN or VRM This is also known as Personally Identifiable Information (PII).', N'High', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Legal', N'Legal content', N'DataClassification', N'AI', N'General', N'Legal content, such as contracts,  statutes, regulations, case law, and legal literature.', N'Medium', 1, 1);
--INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'PII Personal Data - Entites English', NULL, N'DataClassification', N'AI','General', N'', N'High', 0, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Finance', N'', N'DataClassification', N'AI','Data Sensitivity', N'Financial data is content that shares or requests specific personal or corporate financial records or values, such as bank-account or payment-card details, transaction or invoice records, payment details, account balances, financial statements, audit records containing financial figures, budgets containing actual figures, revenue, profit-and-loss, or cash-flow figures. Classify only when concrete financial records, account identifiers, payment details, amounts, or figures are present or requested. Do not classify general discussion of costs, pricing, cost control, budgeting methods, finance processes, accounting concepts, reporting, or auditing when no actual financial data is shared or requested.', N'High', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'HIPAA Health Data', N'', N'DataClassification', N'AI','Data Sensitivity', N'Involves health information in compliance with HIPAA regulations. This includes explicit information such as patient records, personal health information like diagnoses, treatments, and prescriptions, and any data pertaining to an individual''s health status, medical history, or treatment. This does not contain data that does not include explicit HIPAA information.', N'High', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Toxicity', NULL, N'DataClassification', N'AI','Ethics', N'Refers to content that is disrespectful, abusive, or harmful. This includes language and references to physical harm, humiliation, aggression, brutality, explicit sexual content, self-injury, suicidal thoughts, and promoting hatred, discrimination, or violence based on race, ethnicity, religion, gender, sexual orientation, or other characteristics.', N'High', 1, 1)
/****** AI Usage Rules ******/
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Marketing Content', N'', N'AIUsage', N'AI','General', N'Involves creating and refining marketing materials such as blog posts, emails, and social media content to enhance brand engagement and outreach. For example, questions about SEO, content strategy, social media campaigns, and email marketing.', N'None', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Data Analysis', N'', N'AIUsage', N'AI','General', N'Questions involving tools like Excel, SQL, Python, R, etc., for analyzing, interpreting, or visualizing data. This includes tasks like statistical analyses, data visualizations, machine learning, database queries, data cleaning, and report generation. Examples: Excel pivot tables, SQL queries, Python cleaning, R modeling, and Tableau dashboards.', N'None', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Programming', N'', N'AIUsage', N'AI','General', N'Questions involving writing, debugging, and maintaining software code in languages like Python, Java, or C++. This includes tasks like developing features, fixing bugs, and refactoring code. However, it excludes questions about code optimization.', N'Low', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Code Quality Improvement', N'', N'AIUsage', N'AI','General', N'Questions about coding to enhance quality, efficiency, and readability should focus on best practices, code reviews, and optimization. Examples include refactoring, adhering to coding standards, implementing design patterns, static code analysis, breaking down large functions, peer reviews, algorithm optimization, automated testing, and version control.', N'Medium', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Text Improvement', N'', N'AIUsage', N'AI','General', N'Focuses on enhancing the readability, clarity, and stylistic appeal of written content, excluding any programming code. This includes improving grammar, punctuation, vocabulary, sentence structure, and overall coherence in essays, articles, emails, or other written materials.', N'None', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Support Service', N'', N'AIUsage', N'AI','General', N'Involves technical issues, including questions about software installations, network configurations, device setup, and general technical support.', N'None', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'HR Recruitment', N'', N'AIUsage', N'AI','General', N'Involves reviewing resumes and conducting interviews to identify and select the most qualified candidates for job positions.', N'High', 0, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Price Inquiry', N'', N'AIUsage', N'AI','Data Sensitivity', N'Focuses on obtaining and providing specific pricing details for products or services. It does not include activities such as financial forecasting or budgeting, but rather emphasizes the current pricing information available for specific items or services.', N'High', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Customer Service', N'', N'AIUsage', N'AI','General', N'Pertains to feedback or questions from customers regarding company services or products, specifically related to customer service experiences. It includes both complaints and praise, as well as general inquiries about service quality. It does not include answers from the assistant.', N'Medium', 1, 1)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([InternalAccountId], [RuleName], [RuleDescription], [RulePurpose], [RuleType], [RuleCategory], [RuleValue], [SensitivityLevel], [Enabled], [DefaultRule]) VALUES (1, N'Employee Screening', N'', N'AIUsage', N'AI', N'General', N'Process of evaluating potential employees to determine their suitability for a particular job or organization.', N'Medium', 1, 1);
/****** NotebookLM Usage Rules ******/
