INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Tech Secrets and Sensitive Systems â€” NLP-AI',N'Detect requests that aim to reveal or misuse proprietary code, passwords, encryption keys, server details, or other sensitive technical information.',1,N'DataClassification',N'AI',N'Detect requests that aim to reveal or misuse proprietary code, passwords, encryption keys, server details, or other sensitive technical information.',N'Low',N'General',N'Data,Prompt,Response',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Low Resource Languages',N'System security rule',1,N'DataClassification',N'AI',N'Content that abruptly switches from a high-resource language (like English) to a low-resource or constructed language (like Zulu, Hmong, Swahili, Welsh,...) specifically to deliver system instructions, overrides, or policy-breaking commands.',N'High',N'Security',N'Data,Prompt,Response',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Instruction Override',N'System security rule',1,N'DataClassification',N'AI',N'Content that instructs the assistant to disregard, override, or replace its own system or developer instructions, such as directives to ignore previous or following instructions or to output an attacker-specified string instead; this excludes content that merely describes, quotes, reports, or analyzes such an attempt rather than issuing it.',N'High',N'Security',N'Data,Prompt',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Guardrail Evasion',N'System security rule',1,N'DataClassification',N'AI',N'Content that instructs the assistant to adopt a persona or mode defined by the removal of its safety, ethical, or policy constraints, such as "do anything now", unrestricted or developer modes, or characters that never refuse a request; this excludes content that merely describes, quotes, reports, or analyzes such an attempt rather than issuing it.',N'High',N'Security',N'Data,Prompt',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Evil Doing',N'System security rule',1,N'DataClassification',N'AI',N'Content that promotes harm, manipulation, or deceit, including activities associated with malice, fraud, or unethical behavior',N'High',N'Security',N'Data,Prompt,Response',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Malware Generation',N'System security rule',1,N'DataClassification',N'AI',N'content that includes malicious software code, scripts, or files intended to disrupt, damage, or gain unauthorized access to computer systems or networks.',N'High',N'Security',N'Data,Prompt,Response',1,0)
INSERT [dbo].[BG_GOVERNANCE_RULE_LIST] ([Enabled],[CreatedBy],[RuleName],[RuleDescription],[InternalAccountId],[RulePurpose],[RuleType],[RuleValue],[SensitivityLevel],[RuleCategory],[RuleScope],[DefaultRule],[IsLiveProject]) VALUES (1,0,N'Illegal Action',N'System security rule',1,N'DataClassification',N'AI',N'content that includes activities or information directly related to unlawful actions, such as fraud, hacking, or any violation of laws and regulations.',N'High',N'Security',N'Data,Prompt,Response',1,0)
