INSERT [dbo].[BG_GOVERNANCE_POLICY_RULES] ([PolicyId],[RuleId]) SELECT policy.[PolicyId], governanceRule.[RuleId] FROM [dbo].[BG_GOVERNANCE_POLICY_LIST] policy CROSS JOIN [dbo].[BG_GOVERNANCE_RULE_LIST] governanceRule WHERE policy.[InternalAccountId] = 1 AND governanceRule.[InternalAccountId] = 1 AND policy.[PolicyName] = N'Personal Data Protection' AND governanceRule.[RuleName] IN (N'Taiwan National ID', N'Taiwan Business Administration Number (Tax ID)', N'Taiwan NHI Card Number', N'Compliance - Personal Identifiers and Contact Data', N'Compliance - Financial Account and Transaction Data', N'Compliance - Health Genetic and Biometric Data', N'Compliance - Protected Demographic Belief and Sexual Data', N'Compliance - Employment Education Criminal and Social Data')
INSERT [dbo].[BG_GOVERNANCE_POLICY_RULES] ([PolicyId],[RuleId]) SELECT policy.[PolicyId], governanceRule.[RuleId] FROM [dbo].[BG_GOVERNANCE_POLICY_LIST] policy CROSS JOIN [dbo].[BG_GOVERNANCE_RULE_LIST] governanceRule WHERE policy.[InternalAccountId] = 1 AND governanceRule.[InternalAccountId] = 1 AND policy.[PolicyName] = N'Financial Customer Data Protection' AND governanceRule.[RuleName] IN (N'Taiwan National ID', N'Taiwan Business Administration Number (Tax ID)', N'Taiwan NHI Card Number', N'Compliance - Personal Identifiers and Contact Data', N'Compliance - Financial Account and Transaction Data', N'Compliance - Health Genetic and Biometric Data')
INSERT [dbo].[BG_GOVERNANCE_POLICY_RULES] ([PolicyId],[RuleId]) SELECT policy.[PolicyId], governanceRule.[RuleId] FROM [dbo].[BG_GOVERNANCE_POLICY_LIST] policy CROSS JOIN [dbo].[BG_GOVERNANCE_RULE_LIST] governanceRule WHERE policy.[InternalAccountId] = 1 AND governanceRule.[InternalAccountId] = 1 AND policy.[PolicyName] = N'EU GDPR Compliance' AND governanceRule.[RuleName] IN (N'Compliance - Personal Identifiers and Contact Data', N'Compliance - Financial Account and Transaction Data', N'Compliance - Health Genetic and Biometric Data', N'Compliance - Protected Demographic Belief and Sexual Data', N'Compliance - Employment Education Criminal and Social Data')
/****** Training Resource: Project X Classification ******/
DECLARE @ProjectXConfidentialityTrainingName NVARCHAR(255) = N'Workplace Confidentiality Training';
DECLARE @ProjectXConfidentialityTrainingDescription NVARCHAR(MAX) = N'Training Express offers a Workplace Confidentiality Training course that is designed to help individuals understand the importance of maintaining confidentiality in the workplace. This course covers topics such as the legal and ethical obligations of confidentiality, the types of information that should be kept confidential, and the consequences of breaching confidentiality. The course is designed for anyone who works with sensitive information, such as personal data or business secrets, and aims to reduce the risk of breaches that could harm individuals or the company as a whole. This online course is accessible 24/7 and can be completed at the learner''s own pace. Upon completion, learners will receive a certificate of completion';
DECLARE @ProjectXConfidentialityTrainingUrl NVARCHAR(500) = N'https://youtu.be/HjEVbIVbtPo?si=gd48f_t6d-DTCysg';
DECLARE @ProjectXConfidentialityTrainingLengthSeconds INT = 90;
DECLARE @ProjectXConfidentialityTrainingImageFileName NVARCHAR(260) = N'ProjectX training';
DECLARE @ProjectXConfidentialityTrainingLegacyImageFileName NVARCHAR(260) = N'ProjectX training.png';
DECLARE @ProjectXConfidentialityTrainingImageBase64 NVARCHAR(MAX) = CAST(N'' AS NVARCHAR(MAX))
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N''
    + N'';
DECLARE @ProjectXConfidentialityTrainingImage VARBINARY(MAX) = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@ProjectXConfidentialityTrainingImageBase64"))', 'VARBINARY(MAX)');

;WITH ProjectXAccounts AS
(
    SELECT DISTINCT ISNULL([InternalAccountId], 0) AS [InternalAccountId]
    FROM [dbo].[BG_GOVERNANCE_RULE_LIST]
    WHERE [RuleName] = N'Project X Classification'
)
UPDATE image
SET [FileName] = @ProjectXConfidentialityTrainingImageFileName,
    [FileFormat] = N'.png',
    [FileContent] = @ProjectXConfidentialityTrainingImage,
    [FileSize] = DATALENGTH(@ProjectXConfidentialityTrainingImage)
FROM [dbo].[BG_FILE_REPOSITORY] image
INNER JOIN ProjectXAccounts projectXAccounts
    ON projectXAccounts.[InternalAccountId] = image.[CategoryId]
WHERE image.[FileCategory] = N'TrainingImage'
    AND image.[FileName] IN (@ProjectXConfidentialityTrainingImageFileName, @ProjectXConfidentialityTrainingLegacyImageFileName)
    AND (
        image.[FileName] <> @ProjectXConfidentialityTrainingImageFileName
        OR ISNULL(image.[FileFormat], N'') <> N'.png'
        OR ISNULL(image.[FileSize], 0) <> DATALENGTH(@ProjectXConfidentialityTrainingImage)
        OR ISNULL(DATALENGTH(image.[FileContent]), 0) <> DATALENGTH(@ProjectXConfidentialityTrainingImage)
        OR image.[FileContent] <> @ProjectXConfidentialityTrainingImage
    );

;WITH ProjectXAccounts AS
(
    SELECT DISTINCT ISNULL([InternalAccountId], 0) AS [InternalAccountId]
    FROM [dbo].[BG_GOVERNANCE_RULE_LIST]
    WHERE [RuleName] = N'Project X Classification'
)
INSERT [dbo].[BG_FILE_REPOSITORY] ([FileName], [FileFormat], [FileContent], [FileSize], [FileCategory], [CategoryId])
SELECT @ProjectXConfidentialityTrainingImageFileName,
    N'.png',
    @ProjectXConfidentialityTrainingImage,
    DATALENGTH(@ProjectXConfidentialityTrainingImage),
    N'TrainingImage',
    projectXAccounts.[InternalAccountId]
FROM ProjectXAccounts projectXAccounts
WHERE NOT EXISTS
(
    SELECT 1
    FROM [dbo].[BG_FILE_REPOSITORY] image
    WHERE image.[FileCategory] = N'TrainingImage'
        AND image.[CategoryId] = projectXAccounts.[InternalAccountId]
        AND image.[FileName] IN (@ProjectXConfidentialityTrainingImageFileName, @ProjectXConfidentialityTrainingLegacyImageFileName)
);

UPDATE training
SET [Name] = @ProjectXConfidentialityTrainingName,
    [Description] = @ProjectXConfidentialityTrainingDescription,
    [Type] = N'Video',
    [LengthSeconds] = @ProjectXConfidentialityTrainingLengthSeconds,
    [ImageFileId] = CASE
        WHEN projectXImage.[FileId] IS NOT NULL
            AND ISNULL(training.[ImageFileId], '00000000-0000-0000-0000-000000000000') = '00000000-0000-0000-0000-000000000000'
            THEN projectXImage.[FileId]
        ELSE training.[ImageFileId]
    END
FROM [dbo].[BG_TRAINING_RESOURCES] training
INNER JOIN [dbo].[BG_GOVERNANCE_RULE_LIST] projectXRules
    ON projectXRules.[RuleId] = training.[RuleId]
OUTER APPLY
(
    SELECT TOP 1 image.[FileId]
    FROM [dbo].[BG_FILE_REPOSITORY] image
    WHERE image.[FileCategory] = N'TrainingImage'
        AND image.[CategoryId] = ISNULL(projectXRules.[InternalAccountId], 0)
        AND image.[FileName] = @ProjectXConfidentialityTrainingImageFileName
        AND image.[FileFormat] = N'.png'
    ORDER BY image.[FileId]
) projectXImage
WHERE projectXRules.[RuleName] = N'Project X Classification'
    AND training.[URL] = @ProjectXConfidentialityTrainingUrl
    AND (
        ISNULL(training.[Name], N'') <> @ProjectXConfidentialityTrainingName
        OR ISNULL(training.[Description], N'') <> @ProjectXConfidentialityTrainingDescription
        OR ISNULL(training.[Type], N'') <> N'Video'
        OR ISNULL(training.[LengthSeconds], 0) <> @ProjectXConfidentialityTrainingLengthSeconds
        OR (projectXImage.[FileId] IS NOT NULL AND ISNULL(training.[ImageFileId], '00000000-0000-0000-0000-000000000000') = '00000000-0000-0000-0000-000000000000')
    );

;WITH ProjectXRules AS
(
    SELECT [RuleId], ISNULL([InternalAccountId], 0) AS [InternalAccountId]
    FROM [dbo].[BG_GOVERNANCE_RULE_LIST]
    WHERE [RuleName] = N'Project X Classification'
)
INSERT [dbo].[BG_TRAINING_RESOURCES] ([RuleId], [Name], [Description], [URL], [Type], [ImageFileId], [LengthSeconds])
SELECT projectXRules.[RuleId],
    @ProjectXConfidentialityTrainingName,
    @ProjectXConfidentialityTrainingDescription,
    @ProjectXConfidentialityTrainingUrl,
    N'Video',
    projectXImage.[FileId],
    @ProjectXConfidentialityTrainingLengthSeconds
FROM ProjectXRules projectXRules
OUTER APPLY
(
    SELECT TOP 1 image.[FileId]
    FROM [dbo].[BG_FILE_REPOSITORY] image
    WHERE image.[FileCategory] = N'TrainingImage'
        AND image.[CategoryId] = projectXRules.[InternalAccountId]
        AND image.[FileName] = @ProjectXConfidentialityTrainingImageFileName
        AND image.[FileFormat] = N'.png'
    ORDER BY image.[FileId]
) projectXImage
WHERE NOT EXISTS (
    SELECT 1
    FROM [dbo].[BG_TRAINING_RESOURCES] training
    WHERE training.[RuleId] = projectXRules.[RuleId]
        AND training.[URL] = @ProjectXConfidentialityTrainingUrl
);

PRINT(N'+ Seeded Project X workplace confidentiality training resource')

